package cn.edu.techgroup.outsourcing.modules.audit.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.ArgumentMatchers.any;import static org.mockito.Mockito.*;import cn.edu.techgroup.outsourcing.common.error.BusinessException;import cn.edu.techgroup.outsourcing.modules.audit.entity.AuditLogEntity;import cn.edu.techgroup.outsourcing.modules.audit.mapper.AuditLogMapper;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.Map;import org.junit.jupiter.api.Test;import org.mockito.ArgumentCaptor;
class AuditRecorderTest{@Test void serializesSafeSnapshots(){AuditLogMapper m=mock(AuditLogMapper.class);when(m.insert(any(AuditLogEntity.class))).thenReturn(1);new AuditRecorder(m,new ObjectMapper()).record(1L,"UPDATE","USER","2",Map.of("role","MEMBER"),Map.of("role","ADMIN"));ArgumentCaptor<AuditLogEntity> c=ArgumentCaptor.forClass(AuditLogEntity.class);verify(m).insert(c.capture());assertTrue(c.getValue().getAfterData().contains("ADMIN"));}@Test void insertFailureAbortsManagementWrite(){AuditLogMapper m=mock(AuditLogMapper.class);when(m.insert(any(AuditLogEntity.class))).thenReturn(0);assertThrows(BusinessException.class,()->new AuditRecorder(m,new ObjectMapper()).record(1L,"X","Y","1",null,Map.of()));}}
